-- PaperLens PostgreSQL + pgvector schema. Requires PostgreSQL 16 and pgvector.
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TYPE user_role AS ENUM ('ADMIN','RESEARCHER'); CREATE TYPE paper_status AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TABLE users (user_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE CHECK(email ~* '^[^@]+@[^@]+[.][^@]+$'),password_hash TEXT NOT NULL,display_name VARCHAR(120) NOT NULL,role user_role NOT NULL DEFAULT 'RESEARCHER',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE venues (venue_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,venue_type VARCHAR(30) NOT NULL DEFAULT 'CONFERENCE' CHECK(venue_type IN ('CONFERENCE','JOURNAL','WORKSHOP','PREPRINT')));
CREATE TABLE papers (paper_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title VARCHAR(300) NOT NULL UNIQUE,abstract TEXT NOT NULL CHECK(length(abstract)>=40),year SMALLINT NOT NULL CHECK(year BETWEEN 1950 AND 2100),doi VARCHAR(200) UNIQUE,venue_id BIGINT NOT NULL REFERENCES venues(venue_id) ON DELETE RESTRICT,uploaded_by BIGINT REFERENCES users(user_id) ON DELETE SET NULL,status paper_status NOT NULL DEFAULT 'DRAFT',citation_count INTEGER NOT NULL DEFAULT 0 CHECK(citation_count>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE authors (author_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,full_name VARCHAR(160) NOT NULL,orcid VARCHAR(19) UNIQUE CHECK(orcid IS NULL OR orcid ~ '^[0-9]{4}-[0-9]{4}-[0-9]{4}-[0-9X]{4}$'));
CREATE TABLE paper_authors (paper_id BIGINT REFERENCES papers(paper_id) ON DELETE CASCADE,author_id BIGINT REFERENCES authors(author_id) ON DELETE RESTRICT,author_position SMALLINT NOT NULL CHECK(author_position>0),PRIMARY KEY(paper_id,author_id),UNIQUE(paper_id,author_position));
CREATE TABLE topics (topic_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE); CREATE TABLE paper_topics (paper_id BIGINT REFERENCES papers(paper_id) ON DELETE CASCADE,topic_id BIGINT REFERENCES topics(topic_id) ON DELETE RESTRICT,PRIMARY KEY(paper_id,topic_id));
CREATE TABLE paper_relationships (from_paper_id BIGINT REFERENCES papers(paper_id) ON DELETE CASCADE,to_paper_id BIGINT REFERENCES papers(paper_id) ON DELETE CASCADE,relation_type VARCHAR(20) NOT NULL CHECK(relation_type IN ('CITES','EXTENDS','COMPARES')),PRIMARY KEY(from_paper_id,to_paper_id,relation_type),CHECK(from_paper_id<>to_paper_id));
CREATE TABLE paper_chunks (chunk_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,paper_id BIGINT NOT NULL REFERENCES papers(paper_id) ON DELETE CASCADE,chunk_text TEXT NOT NULL CHECK(length(chunk_text)>10),chunk_no SMALLINT NOT NULL CHECK(chunk_no>0),embedding vector(768),embedding_model VARCHAR(100),UNIQUE(paper_id,chunk_no));
CREATE TABLE audit_log (audit_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,paper_id BIGINT,actor_id BIGINT,action VARCHAR(40) NOT NULL,old_data JSONB,new_data JSONB,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX papers_year_idx ON papers(year DESC); CREATE INDEX papers_venue_idx ON papers(venue_id); CREATE INDEX papers_title_fts_idx ON papers USING GIN(to_tsvector('english',title||' '||abstract)); CREATE INDEX chunk_embedding_hnsw_idx ON paper_chunks USING hnsw (embedding vector_cosine_ops) WHERE embedding IS NOT NULL; CREATE INDEX relationship_to_idx ON paper_relationships(to_paper_id);
